import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const outputPath = join(projectRoot, "dist", "app-file.js");
const checkOnly = process.argv.includes("--check");

const modules = [
  { file: "src/core.js", namespace: "SciCore" },
  { file: "src/image-transform.js", namespace: "SciImageTransform" },
  { file: "src/edit-session.js", namespace: "SciEditSession" },
  { file: "src/image-geometry.js", namespace: "SciImageGeometry" },
  { file: "src/i18n.js", namespace: "SciI18n" },
];

const namespaces = new Map(modules.map(({ file, namespace }) => [`./${file.split("/").at(-1)}`, namespace]));

function transformImports(source, owner) {
  return source.replace(
    /^import\s+\{([\s\S]*?)\}\s+from\s+["']([^"']+)["'];/gm,
    (_match, bindings, specifier) => {
      const normalizedSpecifier = specifier.split("?")[0];
      const namespace = namespaces.get(normalizedSpecifier);
      if (!namespace) throw new Error(`${owner} imports unsupported module ${specifier}`);
      const destructuredBindings = bindings.replace(/\s+as\s+/g, ": ").trim();
      return `const {\n${destructuredBindings}\n} = ${namespace};`;
    },
  );
}

function exportedNames(source, file) {
  const names = [...source.matchAll(/^export\s+(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/gm)]
    .map((match) => match[1]);
  if (!names.length) throw new Error(`${file} has no supported named function exports`);
  return names;
}

function stripExports(source) {
  return source.replace(/^export\s+(?=(?:async\s+)?function\s+)/gm, "");
}

async function bundleModule({ file, namespace }) {
  const source = await readFile(join(projectRoot, file), "utf8");
  const names = exportedNames(source, file);
  const body = stripExports(transformImports(source, file));
  return [
    `const ${namespace} = (() => {`,
    body.trim(),
    `return Object.freeze({ ${names.join(", ")} });`,
    "})();",
  ].join("\n");
}

async function createBundle() {
  const moduleBundles = [];
  for (const module of modules) moduleBundles.push(await bundleModule(module));

  const sampleBytes = await readFile(join(projectRoot, "images", "fig1.png"));
  const embeddedAssets = JSON.stringify({
    "images/fig1.png": `data:image/png;base64,${sampleBytes.toString("base64")}`,
  });

  const appSource = await readFile(join(projectRoot, "src", "app.js"), "utf8");
  if (/^export\s/m.test(appSource)) throw new Error("src/app.js must remain an application entry point without exports");
  const appBody = transformImports(appSource, "src/app.js").trim();

  return [
    "/* This file is generated by tools/build-file-bundle.mjs. Do not edit directly. */",
    "(() => {",
    '"use strict";',
    `globalThis.__SCIDIGITIZER_EMBEDDED_ASSETS__ = Object.freeze(${embeddedAssets});`,
    ...moduleBundles,
    "(() => {",
    appBody,
    "})();",
    "})();",
    "//# sourceURL=scidigitizer-app-file.js",
    "",
  ].join("\n");
}

const bundle = await createBundle();

if (checkOnly) {
  let existing = "";
  try {
    existing = await readFile(outputPath, "utf8");
  } catch {
    // Report the same actionable stale-bundle error for a missing output file.
  }
  if (existing !== bundle) {
    console.error("dist/app-file.js is missing or stale; run npm run build:file");
    process.exitCode = 1;
  }
} else {
  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, bundle);
  console.log(`Built ${outputPath} (${(Buffer.byteLength(bundle) / 1024).toFixed(1)} KiB)`);
}
